12	function mainItemBasePremiumOf(item: Item): number {
13	  return MAIN_ITEM_BASE_PREMIUMS[item.type] ?? 0;
14	}
15	
16	export function mainItemsBasePremium(mainItems: readonly Item[]): number {
17	  return mainItems.reduce((sum, item) => sum + mainItemBasePremiumOf(item), 0);
18	}
19	
20	/** Each main item's risk surcharges scale that item's own base premium. */
21	export function mainItemsRiskSurcharges(mainItems: readonly Item[]): number {
22	  return mainItems.reduce(
23	    (sum, item) => sum + riskSurchargeOf(item, mainItemBasePremiumOf(item)),
24	    0,
25	  );
26	}
