import { componentsBasePremium, isComponent } from "./component-block.js";
import { mainItemsBasePremium, mainItemsRiskSurcharges } from "./main-item.js";
import type { Item } from "./quote.js";

/** What the insured items themselves contribute to a premium. */
export interface ItemPricing {
  /** Sum of all item base premiums -- the policy base premium. */
  readonly basePremium: number;
  /** Item-specific risk surcharges, each on its own item's base premium. */
  readonly riskSurcharges: number;
}

/**
 * Each item is priced by the pricing policy that governs its kind:
 * components may form blocks, main items follow the price list.
 */
export function priceItems(items: readonly Item[]): ItemPricing {
  const mainItems = items.filter((item) => !isComponent(item));
  const components = items.filter(isComponent);

  return {
    basePremium:
      mainItemsBasePremium(mainItems) + componentsBasePremium(components),
    riskSurcharges: mainItemsRiskSurcharges(mainItems),
  };
}

